BEGIN;
DO $$
DECLARE u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();s uuid:=gen_random_uuid();i uuid:=gen_random_uuid();a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();req uuid:=gen_random_uuid();t uuid;again uuid;context jsonb;allocs jsonb;items jsonb;r jsonb;saved_risk numeric;aid uuid;bid uuid;cid uuid;denied boolean;count_before integer;
BEGIN
 INSERT INTO auth.users(id,aud,role) VALUES(u,'authenticated','authenticated'),(v,'authenticated','authenticated');
 INSERT INTO public.trading_accounts(id,owner_id,account_name,account_type,default_instrument,default_quantity,default_sl_ticks) VALUES(a,u,'V811 NQ A','demo','NQ',1,40),(b,u,'V811 MNQ','demo','MNQ',5,80),(c,u,'V811 NQ C','demo','NQ',1,100);
 INSERT INTO public.trading_sessions(id,owner_id,session_date,status,htf_context) VALUES(s,u,(clock_timestamp() AT TIME ZONE 'Europe/Berlin')::date,'open',jsonb_build_object('selected_accounts',jsonb_build_array(jsonb_build_object('account_id',a),jsonb_build_object('account_id',b),jsonb_build_object('account_id',c)),'htf_v8',jsonb_build_object('id',gen_random_uuid(),'plan',jsonb_build_object('personal_plan',jsonb_build_object('end_at',clock_timestamp()+interval '1 hour','scope','total'),'news_windows',jsonb_build_array(jsonb_build_object('id','event-fixture','title','Synthetic calendar event','at',clock_timestamp(),'from',clock_timestamp()-interval '5 minutes','to',clock_timestamp()+interval '5 minutes','rule','avoid'))))));
 INSERT INTO public.trade_ideas_v733(id,owner_id,session_id,setup_type,instrument,direction,thesis,trigger_condition,target_zone,invalidation) VALUES(i,u,s,'Momentum','NQ','long','Ursprüngliche eigene These','Originaltrigger','Originalziel','Originalinvalidation');
 INSERT INTO storage.objects(bucket_id,name,owner) VALUES('trading-chart-screenshots',u::text||'/entry/'||req::text||'/original.png',u),('trading-chart-screenshots',v::text||'/entry/'||req::text||'/foreign.png',v);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);EXECUTE 'SET LOCAL ROLE authenticated';
 context:='{"capture_version":737,"documented_after_execution":false,"recording_mode":"planned","execution_mode":"copy","emotion_scales":{"focus":5,"pressure":5,"fomo":5,"revenge":5,"fear":5,"greed":5},"ltf_v811":{"schema":811,"status":"reviewed","timeframe":"m1","reference":"Synthetic session; delta signal candle","values":{"volume":"neutral","stopping":"none","cvd":"flat","delta":"neutral","vpoc":"at","vwap":"at","zone":"middle","zone_direction":"neutral","aggression":"balanced","absorption":"none","liquidity":"both"},"images":[],"image_absence":"not_captured","timing":"before_documented_entry"}}';
 IF NOT public.valid_ltf_v811(context->'ltf_v811') OR public.valid_ltf_v811(jsonb_set(context->'ltf_v811','{values,cvd}','"fabricated"')) THEN RAISE EXCEPTION 'LTF enum validation failed';END IF;
 context:=jsonb_set(context,'{ltf_v811,images}',jsonb_build_array(u::text||'/entry/'||req::text||'/original.png'));
 denied:=false;BEGIN PERFORM public.record_trade_attempt_v811(s,'Momentum','NQ','long','[]','unreported',req,NULL,i,NULL,jsonb_set(context,'{ltf_v811,images}',jsonb_build_array(v::text||'/entry/'||req::text||'/foreign.png')),NULL);EXCEPTION WHEN raise_exception THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Foreign screenshot accepted';END IF;
 allocs:=jsonb_build_array(jsonb_build_object('account_id',a,'instrument','NQ','planned_quantity',1,'initial_sl_ticks',40,'role','leader'),jsonb_build_object('account_id',b,'instrument','MNQ','planned_quantity',5,'initial_sl_ticks',80,'role','follower'),jsonb_build_object('account_id',c,'instrument','NQ','planned_quantity',1,'initial_sl_ticks',100,'role','follower'));
 t:=public.record_trade_attempt_v811(s,'Momentum','NQ','long',allocs,'unreported',req,NULL,i,NULL,context,NULL);
 IF NOT EXISTS(SELECT 1 FROM public.trades WHERE id=t AND initial_risk_usd=900 AND rule_deviation AND observations#>>'{entry_evidence_v811,news_issues,0,type}'='news_window' AND observations#>>'{entry_evidence_v811,idea_snapshot,thesis}'='Ursprüngliche eigene These') THEN RAISE EXCEPTION 'Risk/news/idea snapshot invalid: %',(SELECT to_jsonb(x) FROM public.trades x WHERE id=t);END IF;
 IF (SELECT array_agg(initial_risk_usd ORDER BY initial_risk_usd) FROM public.trade_account_allocations WHERE trade_id=t)<>ARRAY[200,200,500]::numeric[] THEN RAISE EXCEPTION 'NQ/MNQ risk mixed';END IF;
 IF (SELECT jsonb_array_length(observations#>'{entry_evidence_v811,account_changes}') FROM public.trades WHERE id=t)<>0 THEN RAISE EXCEPTION 'Standard match falsely recorded as deviation';END IF;
 UPDATE public.trading_accounts SET default_sl_ticks=50,default_quantity=2 WHERE id=a;
 again:=public.record_trade_attempt_v811(s,'Momentum','NQ','long',allocs,'unreported',req,NULL,i,NULL,context,NULL);
 IF again<>t OR (SELECT initial_risk_usd FROM public.trades WHERE id=t)<>900 THEN RAISE EXCEPTION 'Replay/risk changed';END IF;
 r:=to_jsonb(public.edit_idea_v811(i,0,'{"thesis":"Neue These","trigger_condition":"Neuer Trigger","target_zone":"Neues Ziel","invalidation":"Neue Grenze"}',false));
 IF r->>'revision_v811'<>'1' THEN RAISE EXCEPTION 'Idea revision failed';END IF;
 r:=to_jsonb(public.edit_idea_v811(i,0,'{"thesis":"Neue These","trigger_condition":"Neuer Trigger","target_zone":"Neues Ziel","invalidation":"Neue Grenze"}',false));
 denied:=false;BEGIN PERFORM public.edit_idea_v811(i,0,'{"thesis":"Stale","trigger_condition":"X","target_zone":"Y","invalidation":"Z"}',false);EXCEPTION WHEN raise_exception THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Idea stale overwrite';END IF;
 PERFORM public.edit_idea_v811(i,1,'{"thesis":"Neue These","trigger_condition":"Neuer Trigger","target_zone":"Neues Ziel","invalidation":"Neue Grenze"}',true);
 IF NOT EXISTS(SELECT 1 FROM public.trades WHERE id=t AND observations#>>'{entry_evidence_v811,idea_snapshot,thesis}'='Ursprüngliche eigene These') OR NOT EXISTS(SELECT 1 FROM public.trade_ideas_v733 WHERE id=i AND status='completed') THEN RAISE EXCEPTION 'Archive/history lost';END IF;
 SELECT id INTO aid FROM public.trade_account_allocations WHERE trade_id=t AND account_id=a;
 SELECT id INTO bid FROM public.trade_account_allocations WHERE trade_id=t AND account_id=b;
 SELECT id INTO cid FROM public.trade_account_allocations WHERE trade_id=t AND account_id=c;
 items:=jsonb_build_array(jsonb_build_object('allocation_id',aid,'previous_ticks',-40,'new_ticks',0,'reason','profit_protection'),jsonb_build_object('allocation_id',bid,'previous_ticks',-80,'new_ticks',0,'reason','profit_protection'));req:=gen_random_uuid();
 r:=public.record_stop_batch_v811(req,items);r:=public.record_stop_batch_v811(req,items);
 IF r->>'saved'<>'true' OR (SELECT count(*) FROM public.stop_adjustments WHERE trade_id=t)<>2 OR EXISTS(SELECT 1 FROM public.stop_adjustments WHERE allocation_id=cid) THEN RAISE EXCEPTION 'Selected stop batch/replay failed';END IF;
 denied:=false;BEGIN PERFORM public.record_stop_batch_v811(gen_random_uuid(),jsonb_build_array(jsonb_build_object('allocation_id',aid,'previous_ticks',0,'new_ticks',1,'reason','profit_protection'),jsonb_build_object('allocation_id',bid,'previous_ticks',99,'new_ticks',1,'reason','profit_protection')));EXCEPTION WHEN raise_exception THEN denied:=true;END;IF NOT denied OR (SELECT count(*) FROM public.stop_adjustments WHERE trade_id=t)<>2 THEN RAISE EXCEPTION 'Batch partially committed';END IF;
 PERFORM public.record_stop_batch_v811(gen_random_uuid(),jsonb_build_array(jsonb_build_object('allocation_id',aid,'previous_ticks',0,'new_ticks',-60,'reason','market_structure','notes','Testausnahme im Review bewerten')));
 IF (SELECT initial_risk_usd FROM public.trades WHERE id=t)<>900 THEN RAISE EXCEPTION 'SL changed R denominator';END IF;
 denied:=false;BEGIN UPDATE public.trades SET observations=observations-'entry_evidence_v811' WHERE id=t;EXCEPTION WHEN raise_exception THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Original evidence mutable';END IF;
 denied:=false;BEGIN UPDATE public.trades SET observations=jsonb_set(observations,'{entry_context_v736,ltf_v811,values,delta}','"positive"') WHERE id=t;EXCEPTION WHEN raise_exception THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Historical LTF mutable';END IF;
 -- Real account deviation is captured automatically without becoming a rule breach solely for its size.
 UPDATE public.trading_sessions SET htf_context=jsonb_set(htf_context,'{htf_v8,plan,news_windows}','[]') WHERE id=s;
 req:=gen_random_uuid();context:=jsonb_set(context,'{recording_mode}','"retrospective"')||'{"capture_version":736,"documented_after_execution":true,"execution_mode":"independent","emotion_scales":{},"account_deviation_note":"Bewusste tatsächliche Größe"}'::jsonb;
 context:=jsonb_set(context,'{ltf_v811}','{"status":"not_reviewed","images":[],"image_absence":"historical_unknown","values":{},"timing":"retrospective"}');
 again:=public.record_trade_attempt_v811(s,'Momentum','NQ','short',jsonb_build_array(jsonb_build_object('account_id',a,'instrument','NQ','planned_quantity',1,'initial_sl_ticks',40,'role','leader')),'unreported',req,NULL,NULL,NULL,context,NULL);
 IF NOT EXISTS(SELECT 1 FROM public.trades WHERE id=again AND NOT rule_deviation AND jsonb_array_length(observations#>'{entry_evidence_v811,account_changes}')=2 AND observations#>>'{entry_context_v736,recording_mode}'='retrospective') THEN RAISE EXCEPTION 'Deviation facts/retrospective absence failed';END IF;
 r:=public.export_journal_snapshot_v811();IF NOT r->'tables'?'session_events_v810' OR NOT r->'tables'?'stop_requests_v811' THEN RAISE EXCEPTION 'Audit evidence missing from backup';END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',v,'role','authenticated')::text,true);
 IF EXISTS(SELECT 1 FROM public.stop_requests_v811 WHERE owner_id=u) THEN RAISE EXCEPTION 'Foreign stop request visible';END IF;
 denied:=false;BEGIN PERFORM public.record_stop_batch_v811(gen_random_uuid(),items);EXCEPTION WHEN raise_exception THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Foreign stop writable';END IF;
 denied:=false;BEGIN PERFORM public.edit_idea_v811(i,2,'{"thesis":"Foreign","trigger_condition":"X","target_zone":"Y","invalidation":"Z"}',false);EXCEPTION WHEN raise_exception THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Foreign idea writable';END IF;
 EXECUTE 'RESET ROLE';
END $$;
ROLLBACK;
SELECT 'PASS V811 LTF enums, 900 USD mixed risk, immutable standards/idea, CAS, archive, selected atomic stops/replay, initial-R preservation, retrospective absence, backup and owner isolation' AS result;
